(()=>{'use strict';const slides={zh:[['戶口三位數','錢、壓力與下一個選擇。','由科大同學發起的互動理財企劃。透過故事、遊戲和校園講座，一起練習安排有限資源。','四件失物 · 五款遊戲 · 一個七日行動'],['先查清楚','今天可用，與將來可能有。','阿俊的帳單、收據和訊息提供不同線索。先重建現有資源與付款日期，再作決定。','未到帳的收入，不能當作今天的現金。'],['比較最後總額','需要，還是多買一點？','湊單免運、限時優惠和分期付款，都值得停一停。比較總支出，優先保留基本需要。','小遊戲中的資源不會改動阿俊的戶口。'],['直接開局','五種玩法，同一個資源問題。','植物防守、街頭跑酷、噴射飛行、冰火合作及第一身機械人拆彈。每款遊戲有獨立操作說明，可以跳過故事模式直接試玩。','跑酷與飛行設有所有玩家共享的線上排行榜。'],['留下一步','從短期安排，走向長期目標。','完成主線後，選一個小到做得到的七日行動，並設定檢視日期。記錄中斷後，也可以重新開始。','例如：每晚刷牙後，記下一筆支出。'],['一起見面','9 / 11 與 16 / 11 校園講座。','郭旭昇先生主講「理財有道 創建未來」。活動詳情與報名以團隊 Instagram 最新公布為準。','@poor_guysssss · 歡迎分享試玩連結']],en:[['LOST & FOUND · MONEY JOURNEY','Money, pressure, and your next choice.','An interactive financial-education project initiated by HKUST students. Explore a story, play games, and join campus talks to practise managing limited resources.','Four lost belongings · Five games · One seven-day action'],['INVESTIGATE FIRST','Available today, or expected later?','Ah Jun’s bills, receipts and messages offer different clues. Reconstruct available resources and payment deadlines before deciding what to do.','Expected income is not cash available today.'],['COMPARE THE TOTAL','A real need, or an extra purchase?','Free-shipping thresholds, limited-time offers and instalments deserve a pause. Compare the final cost and protect essential needs first.','Arcade resources never change Ah Jun’s story balance.'],['PLAY YOUR WAY','Five ways to practise resource choices.','Plant defence, street running, jetpack flying, cooperative platform puzzles and first-person robot bomb defence. Each has its own controls; you can play directly without a story introduction.','Running and flying have a shared online leaderboard.'],['KEEP A NEXT STEP','Connect today’s plan to a future goal.','After the main investigation, choose a small seven-day action and a review date. If a habit breaks, you can restart with a manageable step.','Example: after brushing your teeth each evening, record one expense.'],['MEET & LEARN','Campus talks · 9 and 16 November.','Guest speaker 郭旭昇 presents a talk on personal finance and building the future. Visit the team’s Instagram page for the latest event and registration details.','@poor_guysssss · Share the public playtest link']]};let page=0,lang='zh';const $=id=>document.getElementById(id);try{lang=localStorage.getItem('presentation-language')==='en'?'en':'zh'}catch{}function render(){const a=slides[lang][page];['kicker','title','body','detail'].forEach((k,i)=>$('slide-'+k).textContent=a[i]);$('slide-count').textContent=(page+1)+' / '+slides[lang].length;$('slide-prev').textContent=lang==='en'?'← Previous':'← 上一頁';$('slide-next').textContent=lang==='en'?'Next →':'下一頁 →';$('slide-prev').disabled=page===0;$('slide-next').disabled=page===slides[lang].length-1;document.querySelector('.presentation-view').lang=lang==='en'?'en':'zh-Hant';document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===lang)))}function step(n){page=Math.max(0,Math.min(slides[lang].length-1,page+n));render()}$('slide-prev').onclick=()=>step(-1);$('slide-next').onclick=()=>step(1);document.querySelector('.presentation-view').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home')page=0;else if(e.key==='End')page=slides[lang].length-1;else return step(e.key==='ArrowRight'?1:-1);render()}});document.querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>{lang=b.dataset.language;try{localStorage.setItem('presentation-language',lang)}catch{}render()});$('copy-play-link').onclick=async()=>{$('share-url').focus();$('share-url').select();$('share-feedback').textContent='可複製已選取網址 / URL selected';try{await navigator.clipboard.writeText($('share-url').value);$('share-feedback').textContent='已複製 / Link copied'}catch{$('share-url').focus();$('share-url').select();$('share-feedback').textContent='請複製已選取的網址 / Copy the selected URL'}};$('download-play-link').onclick=()=>{const url=URL.createObjectURL(new Blob(['Lost & Found Money Journey — Public playtest\n'+$('share-url').value+'\nInstagram: https://www.instagram.com/poor_guysssss/\n'],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='money-journey-playtest.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render()})();